actions.script:
if (!['read', 'unread', 'archive'].includes(action)) ec.message.addError(ec.l10n.localize('Unknown action') + ': ' + (action || ''))
else ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'set#ThreadState', parameters: {targetList: [{store: store || '', threadId: threadId || ''}],
    action: action}}).call()?.result || {}

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'find#InboxRows', parameters: {view: view || null, emailAccountId: account || null,
    emailFolderId: folder || null, emailLabelId: label || null, contactListId: mailbox || null, searchText: q || null,
    unreadOnly: String(unreadOnly) === 'true', cursor: cursor || null, pageSize: 50}}).call()?.result || {}
// the view's parameters, carried by each action and the next page
viewParams = {}
const given = {view: view, account: account, folder: folder, label: label, mailbox: mailbox, q: q, unreadOnly: unreadOnly}
for (const name of Object.keys(given)) if (given[name] != null && given[name] !== '') viewParams[name] = String(given[name])
const toView = ['sent', 'drafts', 'outbox', 'scheduled', 'internalSent'].includes(view)
const nameOf = (entry) => entry ? (entry.name || String(entry.address || '').split('@')[0] || entry.partyId || '') : ''
threadList = ec.message.hasError() ? [] : Array.from(out.threadList || []).map((row) => {
    const people = Array.from(row.participantList || [])
    const fromText = toView ? ec.l10n.localize('To') + ': ' + people.slice(0, 3).map(nameOf).filter((name) => name).join(', ')
        : (row.fromName || row.fromAddress || nameOf(people[0]) || '')
    const marks = [row.isFlagged ? '*' : '', row.hasAttachment ? '@' : '', Number(row.messageCount || 0) > 1 ? '(' + row.messageCount + ')' : ''].filter((mark) => mark).join(' ')
    return {store: row.store, threadId: row.threadId, isUnread: row.isUnread === true,
        fromText: (row.isUnread ? '● ' : '') + fromText + (marks ? ' ' + marks : ''),
        subjectText: row.subject || ec.l10n.localize('(no subject)'), snippet: row.snippet || '',
        dateText: row.sortDate ? ec.l10n.format(new Date(Number(row.sortDate)), 'MMM d, h:mm a') : '',
        detailEmailMessageId: row.store === 'email' ? (row.lastEmailMessageId || row.emailMessageId || null) : null,
        detailCommEventId: row.store === 'email' ? null : (row.lastCommEventId || row.communicationEventId || null)}
})
hasMore = !ec.message.hasError() && out.hasMore === true && !!out.nextCursor
nextParams = Object.assign({}, viewParams, {cursor: hasMore ? String(out.nextCursor) : ''})
search = {view: view || 'inbox', q: q || ''}
